713: function helperPlanForExecutable(
714:   task: WorksiteExecutionTask,
715:   attemptRef: string,
716:   executable: string,
717: ): WorksiteCommandExecutionHelperPlan {
718:   if (!isWorksiteExecutionTask(task) || !nonempty(attemptRef) ||
719:     !nonempty(executable) || !isAbsolute(executable)) {
720:     throw new TypeError("command helper plan requires one exact task, attempt identity, and absolute executable");
721:   }
722:   const helperModulePath = join(
723:     task.workspaceBinding.roots.toolchainRoot,
724:     "node_modules", "@abiogenesis", "typescript-tenant", "build", "code", "src",
725:     "implementation", "worksite_command_helper.js",
726:   );
727:   const attemptDigest = sha256Canonical({ attemptRef });
728:   const attemptRoot = join(
729:     task.workspaceBinding.roots.archiveRoot,
730:     "worksite-command-execution",
731:     task.taskDigest.slice("sha256:".length),
732:     attemptDigest.slice("sha256:".length),
733:   );
734:   const taskManifestPath = join(attemptRoot, "task.json");
735:   const launchManifestPath = join(dirname(taskManifestPath), "launch.json");
736:   const artifactPath = join(attemptRoot, "result.json");
737:   const sandboxRoot = join(attemptRoot, "sandbox");
738:   const taskBytes = Buffer.from(`${canonicalJson(task as unknown as JsonValue)}\n`, "utf8");
739:   const toolCommand = [
740:     shellQuote(executable), shellQuote(helperModulePath),
741:     "--task", shellQuote(launchManifestPath),
742:   ].join(" ");
743:   const toolInputBytes = Buffer.from(canonicalJson({ command: toolCommand }), "utf8");
744:   return deepFreeze({
745:     kind: "worksite_command_execution_helper_plan" as const,
746:     schemaVersion: SCHEMA_VERSION,
747:     attemptRef,
748:     helperModulePath,
749:     taskManifestPath,
750:     taskManifestDigest: sha256Bytes(taskBytes),
751:     taskManifestByteLength: taskBytes.byteLength,
752:     artifactPath,
753:     sandboxRoot,
754:     toolCommand,
755:     toolInputDigest: sha256Bytes(toolInputBytes),
756:     toolInputByteLength: toolInputBytes.byteLength,
757:   });
758: }
