760: export function isWorksiteCommandExecutionHelperPlan(
761:   task: WorksiteExecutionTask,
762:   value: unknown,
763: ): value is WorksiteCommandExecutionHelperPlan {
764:   if (!isRecord(value) || !exactKeys(value, [
765:     "artifactPath", "attemptRef", "helperModulePath", "kind", "sandboxRoot", "schemaVersion",
766:     "taskManifestByteLength", "taskManifestDigest", "taskManifestPath", "toolCommand",
767:     "toolInputByteLength", "toolInputDigest",
768:   ]) || value.kind !== "worksite_command_execution_helper_plan" ||
769:     value.schemaVersion !== SCHEMA_VERSION || !nonempty(value.attemptRef) ||
770:     typeof value.toolCommand !== "string") return false;
771:   try {
772:     // Only the executable is read from retained command bytes. Every remaining
773:     // command word and all plan coordinates are rederived from task/attempt.
774:     const executableWord = /^'((?:[^']|'"'"')*)' /u.exec(value.toolCommand)?.[1];
775:     if (executableWord === undefined) return false;
776:     const executable = executableWord.replaceAll(`'"'"'`, "'");
777:     return same(value, helperPlanForExecutable(task, value.attemptRef, executable));
778:   } catch {
779:     return false;
780:   }

575: async function materializeSnapshot(
576:   task: WorksiteExecutionTask,
577:   snapshotRoot: string,
578: ): Promise<Readonly<{
579:   snapshotRef: string;
580:   snapshotDigest: `sha256:${string}`;
581:   snapshotMembers: readonly WorksiteExecutionSnapshotMember[];
582: }>> {
583:   await mkdir(snapshotRoot);
584:   const members: WorksiteExecutionSnapshotMember[] = [];
585:   for (const [ordinal, protectedRow] of worksiteExecutionSources(task).entries()) {
586:     const sourcePath = await confinedExistingPath(
587:       task.workspaceAuthorityBasis.canonicalRoot,
588:       protectedRow.subject.relativePath,
589:       "file",
590:     );
591:     const bytes = await readFile(sourcePath);
592:     const digest = sha256Bytes(bytes);
593:     if (digest !== protectedRow.observation.fileDigest ||
594:       bytes.byteLength !== protectedRow.observation.byteLength) {
595:       throw new TypeError("snapshot source bytes differ from protected O1");
596:     }
597:     const targetPath = contained(snapshotRoot, protectedRow.subject.relativePath);
598:     await mkdir(dirname(targetPath), { recursive: true });
599:     await writeFile(targetPath, bytes, { flag: "wx" });
600:     const published = await readFile(targetPath);
601:     if (!published.equals(bytes)) throw new TypeError("snapshot member changed after create-only publication");
602:     members.push(Object.freeze({
603:       ...("sourceMemberRef" in protectedRow && "source" in protectedRow
604:         ? { kind: "worksite_command_forward_snapshot_member" as const, sourceMemberRef: protectedRow.sourceMemberRef, source: protectedRow.source }
605:         : "sourceMemberRef" in protectedRow
606:         ? { kind: "worksite_snapshot_member" as const, sourceMemberRef: protectedRow.sourceMemberRef }
607:         : { kind: "worksite_revision_snapshot_member" as const, designTargetRef: protectedRow.designTargetRef, source: protectedRow.source }),
608:       schemaVersion: "5.0.0" as const,
609:       ordinal,
610:       sourceObservationRef: protectedRow.observation.observationRef,
611:       sourceObservationDigest: protectedRow.observation.observationDigest,
612:       relativePath: protectedRow.subject.relativePath,
613:       byteLength: bytes.byteLength,
614:       digest,
615:     }));
616:   }
617:   const snapshotMembers = Object.freeze(members);
618:   const snapshotDigest = sha256Canonical(snapshotMembers as unknown as JsonValue);
619:   return Object.freeze({
620:     snapshotRef: `${worksiteExecutionIdentityPrefix(task, "snapshot")}/${snapshotDigest.slice("sha256:".length)}`,
621:     snapshotDigest,
622:     snapshotMembers,
623:   });

